ALTER TABLE "commerce"."pages" DROP CONSTRAINT "pages_slug_format";--> statement-breakpoint
ALTER TABLE "commerce"."pages" DROP CONSTRAINT "pages_slug_not_reserved";--> statement-breakpoint
ALTER TABLE "commerce"."pages" DROP CONSTRAINT "pages_store_slug_not_reserved";--> statement-breakpoint
ALTER TABLE "commerce"."pages" ADD CONSTRAINT "pages_slug_format" CHECK ("commerce"."pages"."slug" ~ '^[a-z0-9]+(?:-[a-z0-9]+)*(?:/[a-z0-9]+(?:-[a-z0-9]+)*){0,3}$' and length("commerce"."pages"."slug") <= 240 and "commerce"."pages"."slug" !~ '[^/]{81}' and ("commerce"."pages"."type" = 'page' or position('/' in "commerce"."pages"."slug") = 0));--> statement-breakpoint
ALTER TABLE "commerce"."pages" ADD CONSTRAINT "pages_slug_not_reserved" CHECK ("commerce"."pages"."store_id" is not null or "commerce"."pages"."type" <> 'page' or split_part("commerce"."pages"."slug", '/', 1) not in ('account', 'admin', 'api', 'app', 'auth', 'blog', 'category', 'cookies', 'forgot-password', 'help', 'mail', 'platform', 'robots', 's', 'setup', 'sign-in', 'sign-up', 'sitemap', 'status', 'stores', 'support', 'tag', 'unsubscribe', 'www'));--> statement-breakpoint
ALTER TABLE "commerce"."pages" ADD CONSTRAINT "pages_store_slug_not_reserved" CHECK ("commerce"."pages"."store_id" is null or "commerce"."pages"."type" <> 'page' or split_part("commerce"."pages"."slug", '/', 1) not in ('account', 'blog', 'cart', 'category', 'checkout', 'cookies', 'deliveries', 'download', 'order', 'p', 'products', 'returns', 'search', 'subscription', 'tag', 'unsubscribe', 'wishlist', 'withdraw'));